CREATE TABLE local_users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,name TEXT NOT NULL,email TEXT NOT NULL,password_hash TEXT,status TEXT NOT NULL,operator INTEGER NOT NULL DEFAULT 0,must_change INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE local_sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at INTEGER NOT NULL,last_seen INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX local_session_user ON local_sessions(user_id);
CREATE TABLE event_keys(key TEXT PRIMARY KEY,created_at TEXT NOT NULL);
CREATE TABLE request_results(user_id TEXT NOT NULL,request_id TEXT NOT NULL,response TEXT NOT NULL,status INTEGER NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(user_id,request_id));
ALTER TABLE workspaces ADD COLUMN archived INTEGER NOT NULL DEFAULT 0;
ALTER TABLE attachments ADD COLUMN deleted_at TEXT;
ALTER TABLE attachments ADD COLUMN previous_id TEXT;
ALTER TABLE attachments ADD COLUMN content_hash TEXT;
CREATE TABLE check_items(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,entry_id TEXT NOT NULL,label TEXT NOT NULL,checked INTEGER NOT NULL DEFAULT 0,position INTEGER NOT NULL DEFAULT 0);
CREATE INDEX check_entry ON check_items(workspace_id,entry_id);
CREATE TABLE dependencies(workspace_id TEXT NOT NULL,entry_id TEXT NOT NULL,requires_id TEXT NOT NULL,PRIMARY KEY(entry_id,requires_id));
CREATE TABLE templates(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,author_id TEXT NOT NULL,name TEXT NOT NULL,scope TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE repeat_rules(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,author_id TEXT NOT NULL,name TEXT NOT NULL,period TEXT NOT NULL,next_day TEXT NOT NULL,end_day TEXT,active INTEGER NOT NULL DEFAULT 1,content TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE repeat_occurrences(rule_id TEXT NOT NULL,day TEXT NOT NULL,entry_id TEXT,skipped INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(rule_id,day));
CREATE TABLE handovers(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,entry_id TEXT NOT NULL,from_user TEXT,to_user TEXT NOT NULL,summary TEXT NOT NULL,remaining TEXT NOT NULL,blockers TEXT NOT NULL,resources TEXT NOT NULL,created_at TEXT NOT NULL,accepted_at TEXT);
CREATE TABLE ack_targets(workspace_id TEXT NOT NULL,entry_id TEXT NOT NULL,user_id TEXT NOT NULL,PRIMARY KEY(entry_id,user_id));
CREATE TABLE acknowledgements(entry_id TEXT NOT NULL,user_id TEXT NOT NULL,version INTEGER NOT NULL,confirmed_at TEXT NOT NULL,PRIMARY KEY(entry_id,user_id));
CREATE TABLE room_reads(workspace_id TEXT NOT NULL,entry_id TEXT NOT NULL,user_id TEXT NOT NULL,last_row INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(entry_id,user_id));
CREATE TABLE favorites(workspace_id TEXT NOT NULL,entry_id TEXT NOT NULL,user_id TEXT NOT NULL,PRIMARY KEY(entry_id,user_id));
CREATE TABLE saved_views(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,name TEXT NOT NULL,filters TEXT NOT NULL);
CREATE TABLE ownership_transfers(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,from_user TEXT NOT NULL,to_user TEXT NOT NULL,status TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE author_profiles(user_id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE backup_events(id TEXT PRIMARY KEY,kind TEXT NOT NULL,path TEXT,state TEXT NOT NULL,error TEXT,created_at TEXT NOT NULL);
CREATE TABLE user_preferences(user_id TEXT PRIMARY KEY,deadline_alerts INTEGER NOT NULL DEFAULT 1,reminder_days INTEGER NOT NULL DEFAULT 3);
CREATE TABLE vault_imports(workspace_id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,imported_at TEXT NOT NULL);
